          const dispatchDeviceId = String(dispatch?.nativeRunnerDeviceId || '').trim();
          const dispatchNonce = String(dispatch?.nonce || '').trim();
          const suppliedDispatchNonce = String(body.extensionDispatchNonce || '').trim();
